def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    color = min(colors, key=lambda v: sum(x == v for row in grid for x in row))
    cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
    shape = [(r-r0,c-c0) for r,c in cells]
    out = [row[:] for row in grid]
    for r in range(h-(r1-r0+1)+1):
        for c in range(w-(c1-c0+1)+1):
            if all(grid[r+dr][c+dc] == 0 for dr,dc in shape):
                for dr,dc in shape:
                    out[r+dr][c+dc] = color
    return out
